\label{lem:identities}
For $|q|<1$ and bounded $f$,
\begin{equation}
\begin{aligned}
\mathcal{A}_f(q)&=(q;q)_\infty\sum_{\lambda\in\mathcal{P}}f(\operatorname{lg}(\lambda))q^{|\lambda|}=-\sum_{\lambda\in\mathcal{D}\setminus\{\emptyset\}}\mu_{\mathcal{P}}(\lambda)f(\operatorname{sm}(\lambda))q^{|\lambda|}\\
&=(q;q)_\infty\sum_{n\ge1}\frac{f(n)q^n}{(q;q)_n},
\end{aligned}
\end{equation}
Moreover, for $|q|<1$,
\begin{equation}\label{eq:mass}
\sum_{n\ge1}\omega_n(q)=1-(q;q)_\infty ,
\end{equation}
and $\omega_n(q)>0$ for $0<q<1$.

\label{thm:main}
Let $f:\mathbb{N}\to\mathbb{C}$ be bounded and $L\in\mathbb{C}$. The following are equivalent:
\begin{enumerate}
\item[(i)] $\lim_{q\to1^-}\mathcal{A}_f(q)=L$, that is,
\[
-\lim_{q\to1^-}\sum_{\lambda\in\mathcal{D}\setminus\{\emptyset\}}\mu_{\mathcal{P}}(\lambda)f(\operatorname{sm}(\lambda))q^{|\lambda|}=\lim_{q\to1^-}(q;q)_\infty\sum_{\lambda\in\mathcal{P}}f(\operatorname{lg}(\lambda))q^{|\lambda|}=L;
\]
\item[(ii)] $f$ satisfies $(\mathrm{SI}_L)$.
\end{enumerate}
In particular, for $S\subseteq\mathbb{N}$, $\lim_{q\to1^-}F_S(q)=L$ if and only if
$A_S(x+cx/\log x)-A_S(x)=cLx/\log x+o(x/\log x)$ for every $c>0$.

\label{cor:consequences}
Let $f:\mathbb{N}\to\mathbb{C}$ be bounded.
\begin{enumerate}
\item[(a)] If $\sum_{n\le x}f(n)=dx+o(x/\log x)$, then $\lim_{q\to1^-}\mathcal{A}_f(q)=d$.
\item[(b)] If $\lim_{q\to1^-}\mathcal{A}_f(q)=L$ exists, then $f$ has mean value $M(f)=L$.
\end{enumerate}

\label{thm:counter}
\begin{enumerate}
\item[(a)] Let $\theta>0$ and $0<\delta\le\frac12$. There is a set $S\subseteq\mathbb{N}$ with
\begin{equation}\label{eq:AS-osc}
A_S(x)=\frac x2+\frac{\delta}{\theta}\,\frac{x}{\log x}\,\sin\!\Big(\frac{\theta(\log x)^2}{2}\Big)+O_\theta\Big(\frac{x}{(\log x)^2}\Big),
\end{equation}
such that, as $t\to0^+$,
\begin{equation}\label{eq:FS-osc}
F_S(e^{-t})=\frac12+\delta\,\mathrm{Re}\big(e^{i\theta w(t)}\,\Gamma(1-i\theta)\big)+o(1).
\end{equation}
In particular $\limsup_{q\to1^-}F_S(q)$ and $\liminf_{q\to1^-}F_S(q)$ equal $\frac12\pm\delta\,(\pi\theta/\sinh\pi\theta)^{1/2}$.
\item[(b)] Let $h:[2,\infty)\to(0,\infty)$ satisfy $h(x)\log x/x\to\infty$. There is a set $S\subseteq\mathbb{N}$ with $|A_S(x)-x/2|\le h(x)$ for all sufficiently large $x$ such that
\[
\liminf_{q\to1^-}F_S(q)=0\qquad\text{and}\qquad\limsup_{q\to1^-}F_S(q)=1 .
\]
\end{enumerate}

\label{thm:primes}
Let $S\subseteq\mathbb{N}$, $\alpha\ge0$ and $\delta\ge0$. The following are equivalent:
\begin{enumerate}
\item[(i)] $\displaystyle\lim_{q\to1^-}\Big(\log\frac{1}{1-q}\Big)^{\alpha}F_S(q)=\delta$;
\item[(ii)] for every fixed $c>0$,
\[
A_S\Big(x+\frac{cx}{\log x}\Big)-A_S(x)=\frac{c\,\delta\,x}{(\log x)^{1+\alpha}}+o\Big(\frac{x}{(\log x)^{1+\alpha}}\Big)\qquad(x\to\infty).
\]
\end{enumerate}

\label{thm:periodic}
Let $f$ be periodic modulo $m$, with $\widehat f(j)=\frac1m\sum_{r=1}^mf(r)e^{-2\pi ijr/m}$, and let
\[
\kappa^*=\max\big\{\kappa_\beta(2\pi j/m):\ 1\le j\le m-1,\ \widehat f(j)\ne0\big\}\qquad(\max\emptyset=-\infty).
\]
\begin{enumerate}
\item[(a)] If $\kappa^*<0$, then $\mathcal{A}_f(q_t)\to\widehat f(0)=M(f)$ as $t\to0^+$.
\item[(b)] If $\kappa^*\ge0$, then $\limsup_{t\to0^+}t^{1/2}e^{-\kappa^*/t}\,|\mathcal{A}_f(q_t)|>0$; in particular $\mathcal{A}_f(q_t)$ is unbounded.
\end{enumerate}

\label{lem:muwindows}
Let $S$ satisfy~\eqref{eq:B}.
\begin{enumerate}
\item[(a)] $M_S:=\sup_{w\ge0}\mu_S((w,w+1])<\infty$.
\item[(b)] For $\delta\ge0$, condition~\textup{(ii)} of Theorem~\ref{thm:primes} holds if and only if $\mu_S((w,w+c])\to c\delta$ as $w\to\infty$ for every $c>0$.
\end{enumerate}
